// Daily bookkeeping log — the briefing itself is delivered IN-APP
// (pinned ☀ Briefing session in /agent). Telegram push is disabled by
// design for now: no auto-sends to any account. To re-enable later,
// restore a Send-to-Telegram node AFTER 'Format message' using a
// DEDICATED ops bot (BRIEFING_TELEGRAM_BOT_TOKEN) — never the
// parent-facing bot token — and per-recipient opt-in chat ids.
const b = $input.first().json;
const c = b.counts || {};
console.log(`[morning-briefing] ${b.headline}`);
console.log(`[morning-briefing] needsAction=${c.needsAction ?? 0} followUpsDue=${c.followUpsDue ?? 0} atRisk=${c.atRisk ?? 0} total=${c.total ?? 0} pendingApprovals=${c.pendingApprovals ?? 0}`);
console.log(`[morning-briefing] priority leads: ${(b.priorityLeads || []).map(l => l.name).join(', ') || 'none'}`);
return [{ json: { delivered: 'in_app', sessionId: b.sessionId, runId: b.runId } }];
